"""Original institutional gameplay, not constitutional or historical claims.

Country context comes from the explicitly cited inherited country history.
No individual, electoral result, border or official chronology is invented.
"""
from dataclasses import dataclass


@dataclass(frozen=True)
class Focus:
    suffix: str
    title: str
    desc: str
    x: int
    y: int
    parents: tuple
    reward: str
    motifs: tuple
    excludes: tuple=()
    days: int=35


def row(suffix,title,desc,x,y,parents,reward,motifs,excludes=(),days=35):
    return Focus(suffix,title,desc,x,y,tuple(parents),reward,tuple(motifs),tuple(excludes),days)


